// ─── File: src/main/java/com/bank/closure/service/ClosureDemoService.java ───
package com.bank.closure.service;

import com.bank.closure.dto.ClosureReport;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

@Service
@Slf4j
public class ClosureDemoService {

    // Instance field — NOT a local variable. Accessed via 'this' reference.
    private int processedCount = 0;

    record Trade(String id, String symbol, BigDecimal amount) {}

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "RELIANCE", new BigDecimal("245050")),
        new Trade("TRD-002", "TCS",      new BigDecimal("176000")),
        new Trade("TRD-003", "HDFC",     new BigDecimal("330150"))
    );

    public ClosureReport demonstrate() {
        List<String> explanations = new ArrayList<>();
        processedCount = 0;

        // ═══ 1. VALUE CAPTURE (primitive) — lambda gets a COPY ═══
        int threshold = 200000;  // effectively final
        long countAbove = trades.stream()
            .filter(t -> t.amount().compareTo(BigDecimal.valueOf(threshold)) > 0)
            .count();
        // Lambda captured VALUE 200000. Even if threshold could change, lambda has 200000.
        explanations.add("Primitive: captured VALUE " + threshold + " → " + countAbove + " trades above");

        // ═══ 2. REFERENCE CAPTURE (object) — reference is final, contents mutable ═══
        List<String> collectedSymbols = new ArrayList<>();  // reference is effectively final
        trades.forEach(t -> {
            collectedSymbols.add(t.symbol());  // ✅ Mutating list CONTENTS — allowed!
            // collectedSymbols = new ArrayList<>();  // ❌ Changing REFERENCE — compile error!
        });
        explanations.add("Object: reference to ArrayList is final, but add() mutates contents: "
            + collectedSymbols);

        // ═══ 3. THIS CAPTURE — instance fields mutable ═══
        trades.forEach(t -> {
            processedCount++;  // ✅ Mutating instance field via captured 'this' reference
        });
        explanations.add("this: instance field processedCount mutated inside lambda: " + processedCount);

        // ═══ 4. ATOMIC WORKAROUND — when you need a mutable counter ═══
        AtomicInteger atomicCount = new AtomicInteger(0);  // reference is final
        trades.stream()
            .filter(t -> t.amount().compareTo(new BigDecimal("200000")) > 0)
            .forEach(t -> atomicCount.incrementAndGet());  // ✅ Reference final, value mutable
        explanations.add("AtomicInteger: reference final, incrementAndGet() mutates internal value: "
            + atomicCount.get());

        // ═══ 5. NOT A TRUE CLOSURE ═══
        explanations.add("Java: captures VALUE of local (copy) → effectively final required");
        explanations.add("JavaScript: captures VARIABLE BINDING → variable shared, mutable");
        explanations.add("Java lambda is a 'capture by value' closure, not 'capture by reference'");

        return new ClosureReport(collectedSymbols, processedCount,
            atomicCount.get(), explanations);
    }
}
```

