// ─── File: src/test/java/com/bank/closure/service/ClosureSemanticsTest.java ───
package com.bank.closure.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;

class ClosureSemanticsTest {

    // ═══ Value capture: primitive ═══
    @Test
    void primitiveValueIsCopied() {
        int x = 10;
        Runnable r = () -> assertThat(x).isEqualTo(10);  // captures VALUE 10
        // x = 20;  // If uncommented → compile error at lambda line
        r.run();
    }

    // ═══ Reference capture: object contents mutable ═══
    @Test
    void objectContentsAreMutableThroughCapturedReference() {
        List<String> list = new ArrayList<>();  // reference is effectively final
        Runnable r = () -> list.add("RELIANCE");  // mutating contents ✅
        r.run();
        assertThat(list).containsExactly("RELIANCE");
    }

    @Test
    void objectReferenceCannotBeReassigned() {
        // List<String> list = new ArrayList<>();
        // Runnable r = () -> list.add("X");
        // list = new ArrayList<>();  // ❌ breaks effectively final → lambda won't compile
    }

    // ═══ this capture: instance fields mutable ═══
    private int counter = 0;

    @Test
    void instanceFieldMutableViaThis() {
        counter = 0;
        List.of(1, 2, 3).forEach(n -> counter++);  // 'this' captured, field mutated
        assertThat(counter).isEqualTo(3);
    }

    // ═══ AtomicInteger: mutable value via final reference ═══
    @Test
    void atomicIntegerWorkaround() {
        AtomicInteger count = new AtomicInteger(0);  // reference final
        List.of(1, 2, 3, 4, 5).forEach(n -> count.incrementAndGet());  // value mutated
        assertThat(count.get()).isEqualTo(5);
    }

    // ═══ Not a true closure: doesn't share variable binding ═══
    @Test
    void javaDoesNotShareVariableBinding() {
        // In JavaScript: let x = 1; const f = () => x++; f(); console.log(x); // 2
        // In Java: can't do this with local int — must use AtomicInteger

        AtomicInteger x = new AtomicInteger(1);
        Runnable increment = () -> x.incrementAndGet();
        increment.run();
        assertThat(x.get()).isEqualTo(2);
        // Works, but we're mutating the OBJECT, not the VARIABLE.
        // The variable 'x' (reference) never changed.
    }

    // ═══ Arrays: reference final, contents mutable ═══
    @Test
    void arrayContentsAreMutable() {
        int[] counts = {0};  // array reference is effectively final
        List.of("A", "B", "C").forEach(s -> counts[0]++);  // array contents mutated
        assertThat(counts[0]).isEqualTo(3);
    }
}
```
